enum MemberType     { STUDENT, FACULTY, PUBLIC }
enum MemberStatus   { ACTIVE, BLOCKED, EXPIRED }
enum BookItemStatus { AVAILABLE, LOANED, LOST, MAINTENANCE }
enum LoanStatus     { ACTIVE, RETURNED }
enum FineStatus     { PENDING, PAID }

record Book(String bookId, String title, String author,
            String isbn, String genre) {}

class BookItem {
    private final String barcode;
    private final Book book;
    private volatile BookItemStatus status = BookItemStatus.AVAILABLE;
    private final String location;

    public BookItem(String barcode, Book book, String location) {
        this.barcode = barcode;
        this.book = book;
        this.location = location;
    }

    public synchronized void checkOut() {
        if (status != BookItemStatus.AVAILABLE)
            throw new BookItemNotAvailableException(
                "BookItem " + barcode + " is " + status);
        status = BookItemStatus.LOANED;
    }

    public synchronized void checkIn() {
        if (status != BookItemStatus.LOANED)
            throw new IllegalStateException(
                "Cannot check in item in status " + status);
        status = BookItemStatus.AVAILABLE;
    }

    public synchronized void markLost() {
        status = BookItemStatus.LOST;
    }

    public boolean isAvailable() { return status == BookItemStatus.AVAILABLE; }
    public String getBarcode()   { return barcode; }
    public Book getBook()        { return book; }
}

class Member {
    private final String memberId;
    private final String name;
    private final MemberType type;
    private MemberStatus status = MemberStatus.ACTIVE;
    private int currentLoanCount = 0;
    private long outstandingFines = 0;

    public Member(String memberId, String name, MemberType type) {
        this.memberId = memberId;
        this.name = name;
        this.type = type;
    }

    public boolean canBorrow(BorrowPolicy policy) {
        if (status != MemberStatus.ACTIVE) return false;
        if (outstandingFines > 0) return false;
        return currentLoanCount < policy.getMaxBooks(type);
    }

    public synchronized void incrementLoanCount() { currentLoanCount++; }
    public synchronized void decrementLoanCount() { currentLoanCount--; }
    public void addFine(long amount) { outstandingFines += amount; }
    public void clearFine(long amount) { outstandingFines -= amount; }

    public MemberType getType()       { return type; }
    public String getMemberId()       { return memberId; }
    public MemberStatus getStatus()   { return status; }
    public long getOutstandingFines() { return outstandingFines; }
    public int getCurrentLoanCount()  { return currentLoanCount; }
}

class Loan {
    private final String loanId;
    private final String memberId;
    private final String bookItemBarcode;
    private final LocalDate borrowedAt;
    private final LocalDate dueDate;
    private LocalDate returnedAt;
    private LoanStatus status = LoanStatus.ACTIVE;

    public Loan(String memberId, String barcode, int loanDays) {
        this.loanId = UUID.randomUUID().toString();
        this.memberId = memberId;
        this.bookItemBarcode = barcode;
        this.borrowedAt = LocalDate.now();
        this.dueDate = borrowedAt.plusDays(loanDays);
    }

    public boolean isOverdue() {
        LocalDate checkDate = (returnedAt != null) ? returnedAt : LocalDate.now();
        return checkDate.isAfter(dueDate);
    }

    public long overdueDays() {
        if (!isOverdue()) return 0;
        LocalDate checkDate = (returnedAt != null) ? returnedAt : LocalDate.now();
        return ChronoUnit.DAYS.between(dueDate, checkDate);
    }

    public void markReturned() {
        this.returnedAt = LocalDate.now();
        this.status = LoanStatus.RETURNED;
    }

    public String getLoanId() { return loanId; }
    public String getMemberId() { return memberId; }
    public String getBarcode() { return bookItemBarcode; }
    public LoanStatus getStatus() { return status; }
}

record Reservation(String reservationId, String bookId,
                   String memberId, Instant createdAt) {}
record Fine(String fineId, String loanId, String memberId,
            long amount, FineStatus status) {}

class BorrowPolicy {
    public int getMaxBooks(MemberType type) {
        return switch (type) {
            case STUDENT -> 5;
            case FACULTY -> 10;
            case PUBLIC  -> 3;
        };
    }

    public int getLoanDays(MemberType type) {
        return switch (type) {
            case STUDENT -> 14;
            case FACULTY -> 30;
            case PUBLIC  -> 7;
        };
    }

    public long getFinePerDay(MemberType type) {
        return switch (type) {
            case STUDENT -> 5;   // cents per day
            case FACULTY -> 2;
            case PUBLIC  -> 10;
        };
    }
}

class LibraryService {
    private final Map<String, Book> books = new ConcurrentHashMap<>();
    private final Map<String, BookItem> bookItems = new ConcurrentHashMap<>();
    private final Map<String, Member> members = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Loan> loans = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Fine> fines = new ConcurrentHashMap<>();
    // bookId → FIFO reservation queue
    private final ConcurrentHashMap<String, Queue<Reservation>> reservationQueues =
        new ConcurrentHashMap<>();
    private final BorrowPolicy policy = new BorrowPolicy();

    // ── borrowBook ──────────────────────
    public String borrowBook(String memberId, String barcode) {
        Member member = members.get(memberId);
        if (member == null) throw new IllegalArgumentException("Unknown member");

        BookItem item = bookItems.get(barcode);
        if (item == null) throw new IllegalArgumentException("Unknown item");

        if (!member.canBorrow(policy)) {
            if (member.getOutstandingFines() > 0)
                throw new OutstandingFinesException("Clear fines first");
            if (member.getStatus() != MemberStatus.ACTIVE)
                throw new MemberBlockedException("Member not active");
            throw new MemberLimitExceededException(
                "At limit of " + policy.getMaxBooks(member.getType()));
        }

        // State transition — throws if already loaned
        item.checkOut();

        int loanDays = policy.getLoanDays(member.getType());
        Loan loan = new Loan(memberId, barcode, loanDays);
        loans.put(loan.getLoanId(), loan);
        member.incrementLoanCount();

        return loan.getLoanId();
    }

    // ── returnBook ──────────────────────
    public long returnBook(String loanId) {
        Loan loan = loans.get(loanId);
        if (loan == null) throw new InvalidLoanException(loanId);
        if (loan.getStatus() != LoanStatus.ACTIVE)
            throw new IllegalStateException("Loan already returned");

        Member member = members.get(loan.getMemberId());
        BookItem item = bookItems.get(loan.getBarcode());

        // Compute fine if overdue
        long fineAmount = 0;
        if (loan.isOverdue()) {
            fineAmount = loan.overdueDays() * policy.getFinePerDay(member.getType());
            Fine fine = new Fine(UUID.randomUUID().toString(),
                loanId, member.getMemberId(), fineAmount, FineStatus.PENDING);
            fines.put(fine.fineId(), fine);
            member.addFine(fineAmount);
        }

        // Transition item and loan
        item.checkIn();
        loan.markReturned();
        member.decrementLoanCount();

        // Notify next reserver (Observer-ish)
        notifyNextReserver(item.getBook().bookId());

        return fineAmount;
    }

    // ── reserveBook (when all copies loaned) ──
    public String reserveBook(String memberId, String bookId) {
        Member member = members.get(memberId);
        if (member == null) throw new IllegalArgumentException("Unknown member");
        if (!books.containsKey(bookId))
            throw new IllegalArgumentException("Unknown book");

        Reservation r = new Reservation(
            UUID.randomUUID().toString(), bookId, memberId, Instant.now());
        reservationQueues
            .computeIfAbsent(bookId, k -> new ConcurrentLinkedQueue<>())
            .offer(r);
        return r.reservationId();
    }

    // Called after return — notify first waiter if any
    private void notifyNextReserver(String bookId) {
        Queue<Reservation> queue = reservationQueues.get(bookId);
        if (queue == null || queue.isEmpty()) return;
        Reservation next = queue.poll();
        // In production: send notification (email/push).
        // Here: log it.
        System.out.println("Notifying member " + next.memberId() +
            " — book " + bookId + " is available");
    }

    // ── payFine ─────────────────────────
    public void payFine(String fineId) {
        Fine existing = fines.get(fineId);
        if (existing == null) throw new IllegalArgumentException("Unknown fine");
        if (existing.status() == FineStatus.PAID) return; // idempotent

        Fine paid = new Fine(existing.fineId(), existing.loanId(),
            existing.memberId(), existing.amount(), FineStatus.PAID);
        fines.put(fineId, paid);

        Member m = members.get(existing.memberId());
        if (m != null) m.clearFine(existing.amount());
    }

    // ── Simple search ──────────────────
    public List<Book> searchByTitle(String query) {
        String q = query.toLowerCase();
        return books.values().stream()
            .filter(b -> b.title().toLowerCase().contains(q))
            .toList();
    }

    public List<Book> searchByAuthor(String query) {
        String q = query.toLowerCase();
        return books.values().stream()
            .filter(b -> b.author().toLowerCase().contains(q))
            .toList();
    }

    public List<Book> searchByGenre(String genre) {
        return books.values().stream()
            .filter(b -> b.genre().equalsIgnoreCase(genre))
            .toList();
    }
}
